add(14, ru=("Какой сигнал рукой подаёт водитель, когда хочет замедлиться и остановиться?", "левая согнута в локте, ладонь вверх", "левая рука вытянута горизонтально", "левая рука опущена, ладонь к земле"), es=("¿Qué señal manual debe dar un conductor para reducir y parar?", "el izquierdo doblado en el codo, mano hacia arriba", "brazo izquierdo extendido en horizontal", "brazo izquierdo hacia abajo y mano hacia el suelo"), pt=("Qual sinal de mão o motorista deve dar para reduzir e parar?", "o esquerdo dobrado no cotovelo, mão para cima", "braço esquerdo estendido na horizontal", "braço esquerdo para baixo e mão apontando ao chão"), fr=("Quel geste doit faire un conducteur pour ralentir et s'arrêter ?", "le gauche plié au coude, main vers le haut", "bras gauche tendu à l'horizontale", "bras gauche vers le bas, main vers le sol"), de=("Welches Handzeichen gibt ein Fahrer zum Verlangsamen und Anhalten?", "links im Ellbogen gebeugt, Hand nach oben", "linker Arm waagerecht ausgestreckt", "linker Arm nach unten, Hand zum Boden"))
