add(25, ru=("На перекрёстке без регулирования две машины подъезжают под прямым углом. Кто уступает?", "тот, кто приехал первым", "тот, кто первым замедлился", "тот, кто приехал последним"), es=("En un cruce sin control, dos autos llegan en ángulo recto. ¿Quién debe ceder?", "el que llega primero", "el que reduce primero", "el que llega último"), pt=("Num cruzamento sem controle, dois carros chegam em ângulo reto. Quem deve ceder?", "quem chega primeiro", "quem reduz primeiro", "quem chega por último"), fr=("À un carrefour sans signal, deux voitures arrivent à angle droit. Qui doit céder ?", "celui qui arrive le premier", "celui qui ralentit le premier", "celui qui arrive le dernier"), de=("An einer Kreuzung ohne Regelung kommen zwei Autos im rechten Winkel. Wer muss warten?", "wer zuerst da ist", "wer zuerst langsamer wird", "wer zuletzt ankommt"))
add(26, ru=("На перекрёстке без регулирования две машины едут навстречу одновременно: одна поворачивает налево, другая направо. Кто уступает?", "тот, кто поворачивает направо", "тот, кто поворачивает налево", "тот, кто приехал первым"), es=("En un cruce sin control, dos autos vienen de frente a la vez: uno gira a la izquierda y el otro a la derecha. ¿Quién cede?", "el que gira a la derecha", "el que gira a la izquierda", "el que llega primero"), pt=("Num cruzamento sem controle, dois carros vêm de frente ao mesmo tempo: um vira à esquerda e o outro à direita. Quem cede?", "quem vira à direita", "quem vira à esquerda", "quem chega primeiro"), fr=("Sans signal, deux voitures arrivent en face en même temps : l'une tourne à gauche, l'autre à droite. Qui cède ?", "celui qui tourne à droite", "celui qui tourne à gauche", "celui qui arrive le premier"), de=("Ohne Regelung kommen zwei Autos gleichzeitig entgegen: eines biegt links ab, das andere rechts. Wer muss warten?", "wer rechts abbiegt", "wer links abbiegt", "wer zuerst ankommt"))
add(28, ru=("На перекрёстке без знаков «Стоп» и «Уступи» две машины подъезжают одновременно. У кого преимущество?", "у машины справа", "у машины слева", "у той, что первой замедлилась"), es=("En un cruce sin alto ni ceda el paso, dos autos llegan a la vez. ¿Quién tiene prioridad?", "el auto de la derecha", "el auto de la izquierda", "el que reduce primero"), pt=("Num cruzamento sem pare nem dê a preferência, dois carros chegam juntos. Quem tem a preferência?", "o carro da direita", "o carro da esquerda", "quem reduz primeiro"), fr=("Sans stop ni cédez-le-passage, deux voitures arrivent en même temps. Qui a la priorité ?", "la voiture de droite", "la voiture de gauche", "celle qui ralentit la première"), de=("Ohne Stopp- oder Vorfahrtsschild kommen zwei Autos gleichzeitig an. Wer hat Vorfahrt?", "das Auto rechts", "das Auto links", "wer zuerst langsamer wird"))
add(29, ru=("Машина стоит на перекрёстке, чтобы повернуть налево, и загорается красный. Кто едет первым?", "водитель, застигнутый на перекрёстке и ждущий поворота налево", "водитель, поворачивающий направо", "водитель, которому загорелся зелёный"), es=("Un auto espera en el cruce para girar a la izquierda y el semáforo pasa a rojo. ¿Quién va primero?", "el conductor atrapado en el cruce esperando girar a la izquierda", "el que gira a la derecha", "el que tiene luz verde"), pt=("Um carro espera no cruzamento para virar à esquerda e o sinal fica vermelho. Quem vai primeiro?", "o motorista preso no cruzamento esperando virar à esquerda", "quem vira à direita", "quem pegou o verde"), fr=("Une voiture attend dans le carrefour pour tourner à gauche et le feu passe au rouge. Qui passe en premier ?", "le conducteur bloqué dans le carrefour", "celui qui tourne à droite", "celui qui a le feu vert"), de=("Ein Auto wartet in der Kreuzung aufs Linksabbiegen, und es wird rot. Wer fährt zuerst?", "der Fahrer, der in der Kreuzung aufs Linksabbiegen wartet", "wer rechts abbiegt", "wer Grün hat"))
add(30, ru=("На перекрёстке без знаков «Стоп» и «Уступи» две машины подъезжают с разных улиц. У кого преимущество?", "у той, что уже на перекрёстке", "у той, что слева", "у той, что первой замедлилась"), es=("En un cruce sin alto ni ceda el paso, dos autos llegan por calles distintas. ¿Quién tiene prioridad?", "el que ya está en el cruce", "el de la izquierda", "el que reduce primero"), pt=("Num cruzamento sem pare nem dê a preferência, dois carros vêm de ruas diferentes. Quem tem a preferência?", "o que já está no cruzamento", "o da esquerda", "quem reduz primeiro"), fr=("Sans stop ni cédez-le-passage, deux voitures arrivent de rues différentes. Qui a la priorité ?", "celle déjà dans le carrefour", "celle de gauche", "celle qui ralentit la première"), de=("Ohne Stopp- oder Vorfahrtsschild kommen zwei Autos von verschiedenen Straßen. Wer hat Vorfahrt?", "das Fahrzeug, das schon in der Kreuzung ist", "das von links", "das, das zuerst langsamer wird"))
